public LegendTitle getLegend(int index) {
    if (index < 0) {
        return null;
    }
    int legendIndex = 0;
    for (int i = 0; i < this.subtitles.size(); i++) {
        Title subtitle = (Title) this.subtitles.get(i);
        if (subtitle instanceof LegendTitle) {
            if (legendIndex == index) {
                return (LegendTitle) subtitle;
            }
            legendIndex++;
        }
    }
    return null;
}
